const state=load(); let master={products:[],recipes:[]}; let current=location.hash.slice(1)||'dashboard'; if(!MODULES.some(m=>m[0]===current))current='dashboard';
function load(){let s={};try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))s=parsed}}catch(e){s={}}; if(!Object.keys(s).length){for(const k of LEGACY_KEYS){try{const raw=localStorage.getItem(k);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed)){s=parsed;break}}}catch(e){}}} for(const k of ['products','ingredients','categories','suppliers','purchases','purchasePriceHistory','shopping','inventory','movements','waste','sales','promotions','events','production','labels','notes','records','dreRecords','budgets','recipes','preps','physicalCounts','barcodeLog','barRecipes','barPreps','checklistTasks','managerLogs','incidents','maintenance','equipment','users','audit','employees','employeeDocs','employeeConsumptions','labor','resources','partners','capitalMoves','companyAssets','companyNotes','companyIncidents','companyDocuments','companyResponsibilities','financialDocuments','loans','loanPayments','digitalAssets','permits','refrigerationMoves'])s[k]=Array.isArray(s[k])?s[k]:[];if(!s.users.length)s.users=[{id:'USR-ADMIN',name:'Administrador LRX',role:'Admin',active:true,createdAt:new Date().toISOString()}];s.currentUserId=s.currentUserId||'USR-ADMIN';s.settings={labelFormats:[{name:'4 × 3 in',w:4,h:3},{name:'3 × 2 in',w:3,h:2}],shelfLifeDefault:3,targetFoodCost:30,targetContributionMargin:70,distributionReservePct:30,credentialRevealLog:true,priceIncreaseAlertPct:10,priceIncreaseAlertEnabled:true,inventoryLocations:['Almacén','Cocina','Bar','Nevera','Congelador','Producción'],channels:[{name:'Salón',type:'Directo',commission:0,cardFeePct:0,fixedFee:0,active:true},{name:'Uber Eats',type:'Delivery',commission:49,cardFeePct:0,fixedFee:0,active:true},{name:'DoorDash',type:'Delivery',commission:30,cardFeePct:0,fixedFee:0,active:true},{name:'Pickup',type:'Directo',commission:0,cardFeePct:0,fixedFee:0,active:true}],...(s.settings||{})};return s}
state.masterOverrides=state.masterOverrides&&typeof state.masterOverrides==='object'?state.masterOverrides:{};state.masterHidden=state.masterHidden&&typeof state.masterHidden==='object'?state.masterHidden:{};for(const k of ['products','recipes','preps'])state.masterHidden[k]=Array.isArray(state.masterHidden[k])?state.masterHidden[k]:[];
function effectiveMaster(type){
 const isPrep=type==='preps';
 const isSupplier=type==='suppliers';
 const base=isSupplier?((state.suppliers&&state.suppliers.length)?state.suppliers:(master.suppliers||[]).map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x)):(type==='products'?(master.products||[]):(master.recipes||[]).filter(r=>isPrep?String(r.type||'').toLowerCase()==='pre':String(r.type||'').toLowerCase()!=='pre'));
 const hidden=new Set(state.masterHidden[isPrep?'recipes':type]||[]);
 return base.filter(x=>!hidden.has(String(x.id))).map(x=>({...x,...(state.masterOverrides[isPrep?'recipes':type]?.[x.id]||{})}));
}
function findRecipeAny(type,id){const key=type==='final'?'recipes':'preps';return (state[key]||[]).find(x=>String(x.id)===String(id)) || effectiveMaster(type==='final'?'recipes':'preps').find(x=>String(x.id)===String(id));}
function cloneMasterProduct(id){const base=(master.products||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone={...base,id:'USR-P-'+Date.now(),masterId:base.id,source:'EDITADO DESDE SUP',createdAt:now()};state.products.push(clone);state.masterHidden.products.push(base.id);save();return clone;}
function cloneMasterRecipe(type,id){const key=type==='final'?'recipes':'preps';const base=(master.recipes||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone=JSON.parse(JSON.stringify({...base,id:'USR-'+(type==='final'?'R-':'P-')+Date.now(),masterId:base.id,source:'EDITADO DESDE MAESTRO',createdAt:now()}));state[key].push(clone);state.masterHidden.recipes.push(base.id);save();return clone;}
let lastAction='system';
const ROLE_SECURE={Socio:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},'Accionista/Inversionista':{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},Finanzas:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:false,price:true,cost:true,finance:true},Administración:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},'Gerente General':{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true}};
const ROLES={Admin:{view:true,create:true,edit:true,delete:true,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},Manager:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:true,price:true,cost:true,finance:true},Purchasing:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:false,price:false,cost:true,finance:false},Kitchen:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:false,price:false,cost:true,finance:false},Bar:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:false,price:false,cost:true,finance:false},'POS/Cashier':{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:false,approve:false,discount:true,price:false,cost:false,finance:false},Inventory:{view:true,create:true,edit:true,delete:false,print:true,pdf:true,excel:true,approve:true,discount:false,price:false,cost:true,finance:false}};
function currentUser(){return state.users.find(u=>u.id===state.currentUserId)||state.users[0]||{id:'USR-ADMIN',name:'Administrador LRX',role:'Admin',active:true}}
function lrxNotifications(){const out=[];const pct=Number(state.settings?.priceIncreaseAlertPct||10);if(state.settings?.priceIncreaseAlertEnabled!==false){(state.purchasePriceHistory||[]).slice().reverse().forEach(h=>{if(Number(h.increasePct||0)>=pct)out.push({type:'PRECIO',title:'Aumento de costo',detail:`${h.product||'Producto'} · +${Number(h.increasePct||0).toFixed(1)}%`,date:h.date||h.createdAt})})}(state.permits||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);if(days<=30)out.push({type:'VENCIMIENTO',title:days<0?'Documento vencido':'Vencimiento próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.inventory||[]).forEach(i=>{const min=Number(i.minQty||0);if(min>0&&Number(i.qty||0)<=min)out.push({type:'INVENTARIO',title:'Stock bajo',detail:`${i.product||'Producto'} · ${Number(i.qty||0)} ${i.unit||''}`,date:now()})});return out.slice(0,40)}
function notificationModal(){const rows=lrxNotifications();modal(`<h3>Notificaciones LRX</h3><p class="muted">Alertas operativas pendientes.</p><div class="card">${rows.map(r=>`<div class="check-row" style="display:block;padding:10px 0;border-bottom:1px solid var(--line)"><b>${esc(r.title)}</b><br><small>${esc(r.detail)} · ${esc(r.date||'')}</small></div>`).join('')||'<div class="empty">No hay alertas pendientes.</div>'}</div><div class="actions"><button class="btn primary" data-action="close">Cerrar</button></div>`)}
