function catalog(id,title){
 const isSup=id==='sup';
 return head(title,isSup?'Maestro SUP: productos, proveedor, presentación, costo y rendimiento.':'Catálogo operativo de productos.',isSup?'':'<button class="btn primary" data-action="new-product">＋ Nuevo producto</button>')+
 `<div class="toolbar catalog-tools"><input id="q" class="input search" placeholder="Buscar nombre, categoría, proveedor o código"><select id="size" class="input"><option>25</option><option>50</option><option>100</option><option>250</option><option>381</option></select></div>
 <div id="catalogRows" class="catalog-results"></div><div id="catalogPager" class="pager"></div>`;
}
function catalogSource(){
 const isSup=current==='sup';
 const userProducts=Array.isArray(state.products)?state.products:[];
 const source=isSup?effectiveMaster('products'):[...effectiveMaster('products'),...userProducts];
 const seen=new Set();
 return source.filter(p=>{const key=String(p.id||p.sku||p.name||'').toLowerCase();if(seen.has(key))return false;seen.add(key);return true});
}
function catalogFiltered(){
 const q=(document.getElementById('q')?.value??state._catalogQ??'').toLowerCase().trim();
 state._catalogQ=q;
 return catalogSource().filter(p=>!q||JSON.stringify(p).toLowerCase().includes(q));
}
function catalogRows(){
 const n=Math.max(1,Number(document.getElementById('size')?.value||state._catalogSize||25));
 state._catalogSize=n;
 const all=catalogFiltered();
 const pages=Math.max(1,Math.ceil(all.length/n));
 state._catalogPage=Math.min(Math.max(0,Number(state._catalogPage||0)),pages-1);
 const start=state._catalogPage*n;
 const rows=all.slice(start,start+n);
 const isSup=current==='sup';
 return rows.map(p=>{const user=String(p.id||'').startsWith('USR-');const pack=p.packQty?`${esc(p.packQty)} ${esc(p.unit||'')}`:esc(p.unit||'—');const usable=Number(p.finalCost||0);const yieldPct=p.yieldFactor!=null?`${(Number(p.yieldFactor)*100).toFixed(1)}%`:'—';
 return `<article class="catalog-card"><div class="catalog-main"><div class="catalog-title"><span class="catalog-id">${esc(p.id||'—')}</span><h3>${esc(p.name||'Sin nombre')}</h3></div><div class="catalog-grid"><div><small>Categoría</small><b>${esc(p.category||'—')}</b></div><div><small>Proveedor</small><b>${esc(p.supplier||'—')}</b></div><div><small>Presentación</small><b>${pack}</b></div><div><small>Costo</small><b>${money(p.cost||p.price||0)}</b></div>${isSup?`<div><small>Rendimiento</small><b>${yieldPct}</b></div><div><small>Costo utilizable</small><b>${usable?money(usable):'—'}</b></div>`:''}</div></div><div class="catalog-actions"><button class="btn" data-action="edit-product" data-id="${esc(p.id)}">Editar</button><button class="btn danger" data-action="delete-product" data-id="${esc(p.id)}">Eliminar</button></div></article>`}).join('')||'<div class="card empty">No hay resultados.</div>';
}
function renderCatalog(){
 const el=document.getElementById('catalogRows');if(el)el.innerHTML=catalogRows();
 const pager=document.getElementById('catalogPager');if(!pager)return;
 const all=catalogFiltered();const n=Math.max(1,Number(document.getElementById('size')?.value||state._catalogSize||25));const pages=Math.max(1,Math.ceil(all.length/n));const page=Math.min(Math.max(0,Number(state._catalogPage||0)),pages-1);
 pager.innerHTML=`<div class="pager-info">${all.length?`Mostrando ${page*n+1}–${Math.min((page+1)*n,all.length)} de ${all.length}`:'0 registros'} · Página ${page+1} de ${pages}</div><div class="pager-actions"><button class="btn" data-action="catalog-page-prev" ${page<=0?'disabled':''}>‹ Anterior</button><button class="btn" data-action="catalog-page-next" ${page>=pages-1?'disabled':''}>Siguiente ›</button></div>`;
}
function recipes(type,title){
 const key=type==='final'?'recipes':'preps';const rows=(state[key]||[]).slice().reverse();const masterRows=effectiveMaster(type==='final'?'recipes':'preps');const all=[...rows,...masterRows.filter(m=>!rows.some(r=>String(r.masterId||r.id)===String(m.id)))];
 const q=String(state[`_${type}RecipeQ`]||'').toLowerCase().trim();const filtered=all.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const size=Number(state[`_${type}RecipeSize`]||25);const pages=Math.max(1,Math.ceil(filtered.length/size));state[`_${type}RecipePage`]=Math.min(Math.max(0,Number(state[`_${type}RecipePage`]||0)),pages-1);const page=state[`_${type}RecipePage`];const visible=filtered.slice(page*size,(page+1)*size);
 return head(title,type==='final'?'Recetas finales y su estándar operativo.':'Pre-elaborados reutilizables para recetas y producción.',`<button class="btn primary" data-action="new-recipe" data-type="${type}">＋ Nueva receta</button> <button class="btn" data-action="recipe-print" data-type="${type}">Imprimir / PDF</button> <button class="btn" data-action="recipe-export" data-type="${type}">Excel + CSV</button>`)+`<div class="toolbar"><input id="rq" class="input search" value="${esc(q)}" placeholder="Buscar receta, categoría o ingrediente"><select id="rsize" class="input"><option ${size===25?'selected':''}>25</option><option ${size===50?'selected':''}>50</option><option ${size===100?'selected':''}>100</option><option ${size===250?'selected':''}>250</option></select><span class="pill">${all.length} registros</span></div><div id="recipeResults" class="recipe-results">${visible.map(r=>{const d=recipeCostDetail(r),cost=d.cost,y=Number(r.yieldQty||r.yieldValue||0),uid=String(r.id||'');return `<article class="recipe-card" data-search="${esc(JSON.stringify(r).toLowerCase())}"><div><span class="status">${uid.startsWith('USR-')?'USUARIO':'MAESTRO'}</span><h3>${esc(r.name||'—')}</h3><p>${esc(r.category||r.type||'')}</p>${d.missing.length?`<small class="muted">Revisar: ${esc(d.missing.slice(0,3).join(', '))}</small>`:''}</div><div class="recipe-meta"><div><small>Rendimiento</small><b>${esc(y||r.yield||'—')} ${esc(r.yieldUnit||'')}</b></div><div><small>Costo</small><b>${cost?money(cost):'—'}</b></div><div><small>Costo / unidad</small><b>${y?money(cost/y):'—'}</b></div></div><div class="catalog-actions"><button class="btn" data-action="view-recipe" data-id="${esc(r.id||'')}" data-type="${type}">Ver</button><button class="btn" data-action="edit-recipe" data-id="${esc(r.id||'')}" data-type="${type}">Editar</button><button class="btn danger" data-action="delete-recipe" data-id="${esc(r.id||'')}" data-type="${type}">Eliminar</button></div></article>`}).join('')||'<div class="card empty">No hay recetas.</div>'}</div><div id="recipePager" class="pager"></div>`;
}
function renderRecipePager(type){
 const key=type==='final'?'recipes':'preps';const all=[...(state[key]||[]).slice().reverse(),...effectiveMaster(type==='final'?'recipes':'preps').filter(m=>!(state[key]||[]).some(r=>String(r.masterId||r.id)===String(m.id)))];const q=String(state[`_${type}RecipeQ`]||'').toLowerCase().trim();const filtered=all.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const size=Number(state[`_${type}RecipeSize`]||25);const pages=Math.max(1,Math.ceil(filtered.length/size));const page=Math.min(Math.max(0,Number(state[`_${type}RecipePage`]||0)),pages-1);const pager=document.getElementById('recipePager');if(!pager)return;pager.innerHTML=`<div class="pager-info">${filtered.length?`Mostrando ${page*size+1}–${Math.min((page+1)*size,filtered.length)} de ${filtered.length}`:'0 registros'} · Página ${page+1} de ${pages}</div><div class="pager-actions"><button class="btn" data-action="recipe-page-prev" data-type="${type}" ${page<=0?'disabled':''}>‹ Anterior</button><button class="btn" data-action="recipe-page-next" data-type="${type}" ${page>=pages-1?'disabled':''}>Siguiente ›</button></div>`;
}
function recipeOptions(){const products=effectiveMaster('products'),preps=effectiveMaster('preps');return [...products.map(p=>`<option value="${esc(p.name)}" data-product-id="${esc(p.id)}">${esc(p.name)} · ${money(p.finalCost||p.cost||p.price||0)}/${esc(p.unit||'u')}</option>`),...preps.map(p=>`<option value="${esc(p.name)}" data-prep-id="${esc(p.id)}">${esc(p.name)} · PREP · ${money(recipeOutputCost(p))}/${esc(p.yieldUnit||'u')}</option>`)].join('')}
function recipeViewModal(r,type){const items=Array.isArray(r?.items)?r.items:[];modal(`<div class="print-target operational-recipe"><h2>La Reyna Xpress</h2><h1>Receta Estándar</h1><p><b>${esc(r?.name||'Receta')}</b> · ${type==='final'?'Receta final':'Pre-elaborado'}</p><div class="formgrid"><div><b>Departamento</b><br>${esc(r?.category||r?.department||'Cocina')}</div><div><b>Rendimiento</b><br>${esc(r?.yieldQty||r?.yield||'—')} ${esc(r?.yieldUnit||'')}</div><div><b>Vida útil</b><br>${esc(r?.shelfLife||'—')}</div><div><b>Almacenamiento</b><br>${esc(r?.storage||'—')}</div></div><div class="card"><h3>Ingredientes / componentes</h3>${items.map(x=>`<div class="recipe-standard-line"><b>${esc(x.ingredient||x.product||x.name||'—')}</b><span>${esc(x.qty||0)} ${esc(x.unit||'')}</span></div>`).join('')||'<p>Sin componentes registrados.</p>'}</div><div class="card"><h3>Procedimiento</h3><div class="standard-text">${esc(r?.method||r?.procedure||r?.instructions||'No registrado.')}</div></div><div class="card"><h3>Servicio / montaje</h3><div class="standard-text">${esc(r?.plating||r?.service||'No registrado.')}</div></div><div class="card"><h3>Notas de almacenamiento</h3><div class="standard-text">${esc(r?.storageNotes||r?.notes||'No registradas.')}</div></div></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="generic-print">Imprimir / Guardar PDF</button></div>`) }
function recipeModal(type,id){
 const key=type==='final'?'recipes':'preps';const r=id?findRecipeAny(type,id):null;const title=r?'Editar receta':(type==='final'?'Nueva receta final':'Nuevo pre-elaborado');const items=(r?.items||[]);const rows=items.length?items:[{product:'',qty:'',unit:'lb'}];
 modal(`<h3>${title}</h3><div class="formgrid"><div class="field"><label>Nombre</label><input id="rn" value="${esc(r?.name||'')}"></div><div class="field"><label>Categoría / departamento</label><input id="rc" value="${esc(r?.category||'Cocina')}"></div><div class="field"><label>Rendimiento</label><input id="ry" type="number" step="0.001" value="${esc(r?.yieldQty||'')}"></div><div class="field"><label>Unidad de rendimiento</label><select id="ru"><option ${r?.yieldUnit==='lb'?'selected':''}>lb</option><option ${r?.yieldUnit==='oz'?'selected':''}>oz</option><option ${r?.yieldUnit==='kg'?'selected':''}>kg</option><option ${r?.yieldUnit==='unidad'?'selected':''}>unidad</option><option ${r?.yieldUnit==='L'?'selected':''}>L</option><option ${r?.yieldUnit==='lt'?'selected':''}>lt</option></select></div><div class="field"><label>Precio de venta</label><input id="rp" type="number" step=".01" value="${Number(r?.salePrice||r?.price||0)}"></div></div><div class="card" style="margin-top:12px"><div class="rowhead"><h4>Ingredientes / componentes</h4><button class="btn" id="addIng">＋ Agregar ingrediente</button></div><datalist id="productChoices">${recipeOptions()}</datalist><div id="ingredientRows">${rows.map((x,i)=>recipeRow(x,i)).join('')}</div><div class="recipe-total"><b>Costo total:</b> <strong id="recipeCost">$0.00</strong> <span id="recipeUnitCost"></span></div></div><div class="actions" style="margin-top:12px"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="saveRecipe">Guardar receta</button></div>`);
 const box=document.getElementById('ingredientRows');document.getElementById('addIng').onclick=()=>{box.insertAdjacentHTML('beforeend',recipeRow({product:'',qty:'',unit:'lb'},box.children.length));bindRecipeRows();calculateRecipe()};document.getElementById('saveRecipe').onclick=()=>saveRecipe(type,id);bindRecipeRows();calculateRecipe();
}
function recipeRow(x,i){return `<div class="recipe-row" data-i="${i}"><input class="ri-product input" list="productChoices" placeholder="Producto / ingrediente" value="${esc(x.product||x.ingredient||'')}"><input class="ri-qty input" type="number" step="0.001" placeholder="Cantidad" value="${esc(x.qty??'')}"><select class="ri-unit input"><option ${x.unit==='lb'?'selected':''}>lb</option><option ${x.unit==='oz'?'selected':''}>oz</option><option ${x.unit==='kg'?'selected':''}>kg</option><option ${x.unit==='g'?'selected':''}>g</option><option ${x.unit==='unidad'?'selected':''}>unidad</option><option ${x.unit==='L'?'selected':''}>L</option><option ${x.unit==='mL'?'selected':''}>mL</option><option ${x.unit==='lt'?'selected':''}>lt</option></select><span class="ri-cost">$0.00</span><button type="button" class="btn danger ri-remove">×</button></div>`}
function sharedProduct(name,id){const key=String(name||'').trim().toLowerCase();const masterId=id?String(id):'';const base=(master.products||[]).find(p=>(masterId&&String(p.id)===masterId)||String(p.name||'').trim().toLowerCase()===key);const override=base?(state.masterOverrides?.products?.[base.id]||{}):{};const local=(state.products||[]).find(p=>(masterId&&String(p.id)===masterId)||String(p.name||'').trim().toLowerCase()===key);const inv=(state.inventory||[]).find(x=>(masterId&&String(x.productId||'')===masterId)||String(x.product||'').trim().toLowerCase()===key);const p={...(base||{}),...override,...(local||{})};if(!Object.keys(p).length)return null;if(inv&&Number.isFinite(Number(inv.unitCost))&&Number(inv.unitCost)>0)p.cost=Number(inv.unitCost);return p}
function upsertLocalProductCost(productId,name,patch){
 const key=String(name||'').trim().toLowerCase();
 let p=(state.products||[]).find(x=>(productId&&String(x.id)===String(productId))||String(x.name||'').trim().toLowerCase()===key);
 if(!p){const m=(master.products||[]).find(x=>(productId&&String(x.id)===String(productId))||String(x.name||'').trim().toLowerCase()===key);if(!m)return null;p={...m,id:m.id||'P-'+Date.now(),source:'MASTER_OVERRIDE'};state.products.push(p)}
 Object.assign(p,patch,{updatedAt:now()});return p}
function findCost(name){const p=sharedProduct(name);return p?Number(p.finalCost||p.cost||p.price||0):0}
function unitToBase(q,u){const m={g:1,oz:28.349523125,lb:453.59237,kg:1000};const v={mL:1,'fl oz':29.5735295625,L:1000,lt:1000,pt:473.176473,qt:946.352946,gal:3785.411784};if(m[u])return {group:'mass',v:q*m[u]};if(v[u])return {group:'vol',v:q*v[u]};return {group:'unit',v:q}}
function calculateRecipe(){let total=0;document.querySelectorAll('.recipe-row').forEach(row=>{const name=row.querySelector('.ri-product')?.value||'';const q=Number(row.querySelector('.ri-qty')?.value||0);const u=row.querySelector('.ri-unit')?.value||'lb';let c=findCost(name);const p=(master.products||[]).find(x=>String(x.name).toLowerCase()===name.toLowerCase());if(p&&p.unit&&p.unit!==u){const a=unitToBase(1,p.unit),b=unitToBase(q,u);if(a.group===b.group)c*=b.v/a.v;else c*=q}else c*=q;total+=c;const out=row.querySelector('.ri-cost');if(out)out.textContent=money(c)});const y=Number(document.getElementById('ry')?.value||0);const rc=document.getElementById('recipeCost');if(rc)rc.textContent=money(total);const ru=document.getElementById('ru')?.value||'u';const ruc=document.getElementById('recipeUnitCost');if(ruc)ruc.textContent=y?`· ${money(total/y)} por ${ru}`:'';return total}
function bindRecipeRows(){document.querySelectorAll('.recipe-row').forEach(row=>{const input=row.querySelector('.ri-product');const syncLink=()=>{const value=input.value.trim().toLowerCase();const option=[...(master.products||[]),...effectiveMaster('preps')].find(x=>String(x.name||'').trim().toLowerCase()===value);delete input.dataset.productId;delete input.dataset.prepId;if(option){if((master.products||[]).some(x=>String(x.id)===String(option.id)))input.dataset.productId=option.id;else input.dataset.prepId=option.id}};row.querySelectorAll('input,select').forEach(x=>x.oninput=()=>{if(x===input)syncLink();calculateRecipe()});syncLink();row.querySelector('.ri-remove').onclick=()=>{if(document.querySelectorAll('.recipe-row').length>1){row.remove();calculateRecipe()}}})}
function saveRecipe(type,id){const name=document.getElementById('rn').value.trim(),y=Number(document.getElementById('ry').value||0);if(!name||y<=0)return toast('Indica nombre y rendimiento');const items=[...document.querySelectorAll('.recipe-row')].map(r=>{const input=r.querySelector('.ri-product'),product=input.value.trim(),qty=Number(r.querySelector('.ri-qty').value||0),unit=r.querySelector('.ri-unit').value;let productId=input.dataset.productId||'',prepId=input.dataset.prepId||'';const p=(master.products||[]).find(x=>String(x.id)===String(productId))||((master.products||[]).find(x=>String(x.name||'').trim().toLowerCase()===product.toLowerCase()));const prep=effectiveMaster('preps').find(x=>String(x.id)===String(prepId))||effectiveMaster('preps').find(x=>String(x.name||'').trim().toLowerCase()===product.toLowerCase());productId=p?.id||productId||undefined;prepId=prep?.id||prepId||undefined;return {product,ingredient:product,productId,prepId,qty,unit}}).filter(x=>x.product&&x.qty>0);if(!items.length)return toast('Agrega al menos un ingrediente');const cost=calculateRecipe();const key=type==='final'?'recipes':'preps';let r=id?(state[key]||[]).find(x=>x.id===id):null;if(!r){r={id:'USR-R-'+Date.now(),createdAt:now()};state[key].push(r)}Object.assign(r,{name,category:document.getElementById('rc').value.trim(),yieldQty:y,yieldUnit:document.getElementById('ru').value,salePrice:Number(document.getElementById('rp')?.value||0),items,cost,type:type==='final'?'final':'pre',source:'LOCAL',updatedAt:now()});save();close();render();toast('Receta guardada y vinculada al maestro SUP')}

function reverseProductionInventory(p){
 if(!p)return {ok:false,reason:'Producción inexistente'};
 const out=p.inventoryOutput;
 const outputQty=Number(p.qty||0);
 // Preflight: verify the produced stock can be reversed before changing ANY ingredient stock.
 if(out?.record && Number(out.record.qty||0)+1e-9<outputQty){
  return {ok:false,reason:`La producción ${p.product} ya fue consumida parcialmente por ventas u otros movimientos.`};
 }
 const seen=[];
 for(const x of (p.inventoryConsumption||[])){
  const rec=invRecord(x.product,x.unit,0,x.productId||''),q=Number(x.qty||0);
  if(q<=0)continue;
  rec.qty=Number(rec.qty||0)+q;
  state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:now(),type:'REVERSA CONSUMO PRODUCCIÓN',product:x.product,qty:q,unit:x.unit,unitCost:Number(x.unitCost||rec.unitCost||0),total:q*Number(x.unitCost||0),ref:p.id});
  seen.push(`${x.product||''} +${q} ${x.unit||''}`);
 }
 if(out?.record && outputQty>0){
  const rec=invRecord(p.product,p.unit,0,p.productId||out.record?.productId||p.recipeId||'');
  if(Number(rec.qty||0)+1e-9<outputQty)return {ok:false,reason:`No hay inventario suficiente de ${p.product} para revertir la producción.`};
  rec.qty=Number(rec.qty||0)-outputQty;
  state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:now(),type:'REVERSA PRODUCCIÓN TERMINADA',product:p.product,qty:-outputQty,unit:p.unit,unitCost:Number(p.costPerUnit||rec.unitCost||0),total:-outputQty*Number(p.costPerUnit||rec.unitCost||0),ref:p.id});
  seen.push(`${p.product||''} -${outputQty} ${p.unit||''}`);
 }
 state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:now(),type:'REVERSA PRODUCCIÓN',product:p.product,qty:0,unit:p.unit,ref:p.id,notes:seen.join(', ')});
 return {ok:true};
}
function editProductionModal(id){
 const p=state.production.find(x=>String(x.id)===String(id)); if(!p)return;
 modal(`<h3>Editar producción</h3><div class="formgrid"><div class="field full"><label>Producto / receta</label><input id="epProduct" value="${esc(p.product||'')}" ${p.status==='completed'?'readonly':''}></div><div class="field"><label>Departamento</label><input id="epDept" value="${esc(p.department||'')}"></div><div class="field"><label>Cantidad</label><input id="epQty" type="number" step="0.001" value="${Number(p.qty||0)}" ${p.status==='completed'?'readonly':''}></div><div class="field"><label>Unidad</label><input id="epUnit" value="${esc(p.unit||'')}" ${p.status==='completed'?'readonly':''}></div><div class="field"><label>Elaboró</label><input id="epEmployee" value="${esc(p.employee||'')}"></div><div class="field"><label>Vida útil</label><input id="epLife" type="number" value="${Number(p.shelfLife||0)}"></div><div class="field full"><label>Notas</label><textarea id="epNotes" rows="3">${esc(p.notes||'')}</textarea></div></div><p class="muted">${p.status==='completed'?'La producción finalizada conserva sus movimientos; aquí se editan datos administrativos.':'La producción en proceso puede corregirse antes de finalizar.'}</p><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="update-production" data-id="${esc(id)}">Guardar</button></div>`);
}
function updateProduction(id){const p=state.production.find(x=>String(x.id)===String(id));if(!p)return;Object.assign(p,{department:document.getElementById('epDept').value.trim(),employee:document.getElementById('epEmployee').value.trim(),shelfLife:Number(document.getElementById('epLife').value||0),notes:document.getElementById('epNotes').value.trim()});if(p.status!=='completed'){p.product=document.getElementById('epProduct').value.trim();p.qty=Number(document.getElementById('epQty').value||0);p.unit=document.getElementById('epUnit').value.trim()||p.unit;}save();close();render();toast('Producción actualizada')}
function reverseProductionRefrigeration(p){
 if(!p)return {ok:false,reason:'Producción inexistente'};
 const moves=(state.refrigerationMoves||[]).filter(m=>String(m.productionId||'')===String(p.id));
 if(!moves.length)return {ok:true};
 const net=moves.reduce((a,m)=>a+(String(m.type).toUpperCase()==='SALIDA'?-1:1)*Number(m.qty||0),0);
 if(net<=0)return {ok:true};
 const summary=fridgeSummary()[String(p.productId||p.recipeId||p.product||'').toLowerCase()];
 if(!summary || Number(summary.qty||0)+1e-9<net)return {ok:false,reason:`No se puede eliminar ${p.product}: la producción ya salió parcialmente de la nevera.`};
 state.refrigerationMoves.push({id:'FRG-'+Date.now()+'-REV',date:now(),type:'SALIDA',product:p.product,productId:p.productId||p.recipeId||'',qty:net,unit:p.unit||'u',responsible:currentUser().name||'',productionId:p.id,notes:'Reversión por eliminación de producción',createdAt:now()});
 return {ok:true};
}
function deleteProduction(id){const p=state.production.find(x=>String(x.id)===String(id));if(!p)return;if(!confirm('¿Eliminar esta producción? Si ya estaba finalizada, se revertirán sus movimientos de inventario y nevera.'))return;if(p.status==='completed'){const rev=reverseProductionInventory(p);if(!rev.ok)return toast(rev.reason);const fridgeRev=reverseProductionRefrigeration(p);if(!fridgeRev.ok)return toast(fridgeRev.reason);}state.production=state.production.filter(x=>x.id!==id);state.labels=(state.labels||[]).filter(x=>x.productionId!==id);save();render();toast('Producción eliminada y movimientos revertidos')}
function cocina(){
 const prod=(state.production||[]).slice().reverse(), completed=prod.filter(x=>x.status==='completed'), pending=prod.filter(x=>x.status!=='completed');
 const waste=(state.waste||[]).slice().reverse(), incidents=(state.incidents||[]).slice().reverse(), today=new Date().toISOString().slice(0,10);
 const todayProd=completed.filter(x=>String(x.finishedAt||'').slice(0,10)===today);
 const groups=['Apertura','Mise en Place','Servicio','Cierre'];
 return head('Cocina','Centro operativo de cocina: apertura, mise en place, producción, pérdidas, temperaturas y cierre.',`<button class="btn primary" data-action="new-kitchen-note">＋ Nota de cocina</button> <button class="btn" data-action="new-production">＋ Producción</button> <button class="btn" data-action="kitchen-print">Imprimir / PDF</button> <button class="btn" data-action="kitchen-export">Excel + CSV</button>`)+
 `<div class="grid"><div class="card kpi"><small>Producción hoy</small><strong>${todayProd.length}</strong></div><div class="card kpi"><small>En proceso</small><strong>${pending.length}</strong></div><div class="card kpi"><small>Merma registrada</small><strong>${waste.length}</strong></div><div class="card kpi"><small>Incidentes abiertos</small><strong>${incidents.filter(x=>String(x.status||'ABIERTO').toUpperCase()!=='CERRADO').length}</strong></div></div>`+
 `<div class="grid" style="margin-top:14px"><div class="card"><h3>Operación por turno</h3>${groups.map(g=>`<button class="kitchen-card" data-action="kitchen-section" data-section="${g}"><b>${g}</b><span>Ver tareas y registros de esta etapa →</span></button>`).join('')}</div><div class="card"><h3>Producción disponible</h3>${completed.slice(0,8).map(x=>`<div class="kitchen-line"><b>${esc(x.product)}</b><span>${esc(x.qty)} ${esc(x.unit)} · ${fmt(x.finishedAt,true)}</span><small>Lote ${esc(x.lot||'—')} · ${esc(x.employee||'—')}</small></div>`).join('')||'<div class="empty">Sin producción finalizada.</div>'}</div></div>`+
 `<div class="grid" style="margin-top:14px"><div class="card"><h3>Pérdidas / merma recientes</h3>${waste.slice(0,8).map(x=>`<div class="kitchen-line"><b>${esc(x.product)}</b><span>${Number(x.wastePct||0).toFixed(1)}% · ${money(x.wasteCost)}</span><small>${esc(x.reason||'Sin razón registrada')}</small></div>`).join('')||'<div class="empty">Sin mermas registradas.</div>'}</div><div class="card"><h3>Notas de cocina</h3>${(state.records||[]).filter(x=>x.area==='Cocina').slice().reverse().slice(0,8).map(x=>`<div class="kitchen-line"><b>${esc(x.title||x.description||'Nota')}</b><span>${fmt(x.date||x.createdAt,true)}</span><small>${esc(x.description||x.body||'')}</small></div>`).join('')||'<div class="empty">No hay notas de cocina.</div>'}</div></div>`;
}
function production(){
 const rows=state.production.slice().reverse(), active=rows.filter(p=>p.status!=='completed').length;
 const moves=state.refrigerationMoves||[], summary=fridgeSummary(), recent=moves.slice().reverse().slice(0,12);
 return head('Producción','Controla producción, tiempos, productividad, flujo de nevera y etiquetas de cada elaboración.',`<button class="btn primary" data-action="new-production">＋ Nueva producción</button> <button class="btn" data-action="fridge-move">＋ Movimiento nevera</button> <button class="btn" data-action="fridge-report">Reporte de flujo</button> <button class="btn" data-action="fridge-planning">Planeación 7/30/90 días</button> <button class="btn" data-action="fridge-export">Excel + CSV</button>`)+
 `<div class="grid"><div class="card kpi"><small>Producciones</small><strong>${rows.length}</strong></div><div class="card kpi"><small>En proceso</small><strong>${active}</strong></div><div class="card kpi"><small>Producción terminada</small><strong>${rows.filter(p=>p.status==='completed').length}</strong></div><div class="card kpi"><small>Etiquetas generadas</small><strong>${(state.labels||[]).length}</strong></div></div>`+
 `<div class="grid" style="margin-top:14px"><div class="card"><h3>Nevera / producción disponible</h3><p class="muted">Control de entradas, salidas y existencia de producto preparado. No modifica el Food Cost estándar.</p>${Object.values(summary).sort((a,b)=>a.product.localeCompare(b.product)).slice(0,12).map(x=>`<div class="kitchen-line"><b>${esc(x.product)}</b><span>${fmtNum(x.qty)} ${esc(x.unit)} · ${x.moves} movimientos</span><small>Entradas ${fmtNum(x.in)} · Salidas ${fmtNum(x.out)} · Cobertura/flujo: ${fmtNum(x.avgDaily,2)} ${esc(x.unit)}/día</small></div>`).join('')||'<div class="empty">No hay producto registrado en nevera.</div>'}</div><div class="card"><h3>Flujo reciente</h3>${recent.map(x=>`<div class="kitchen-line"><b>${esc(x.product)}</b><span>${x.type==='SALIDA'?'−':'+'}${fmtNum(x.qty)} ${esc(x.unit)}</span><small>${esc(x.type)} · ${fmt(x.date,true)} · ${esc(x.responsible||'—')}</small></div>`).join('')||'<div class="empty">Sin movimientos.</div>'}</div></div>`+
 `<div class="card" style="margin-top:14px"><h3>Producción y productividad</h3><div class="tablewrap"><table><thead><tr><th>Producto / receta</th><th>Inicio</th><th>Finalizada</th><th>Duración</th><th>Empleado</th><th>Costo laboral observado</th><th>Equipo</th><th>Cantidad</th><th>Lote</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.product)}</b>${p.recipe?`<small class="muted">Receta: ${esc(p.recipe)}</small>`:''}</td><td>${fmt(p.startedAt,true)}</td><td>${fmt(p.finishedAt,true)}</td><td>${esc(p.duration||'—')}</td><td>${esc(p.employee||'—')}</td><td>${p.status==='completed'?money(p.laborCostObserved||0):'—'}<small class="muted">No modifica Food Cost</small></td><td>${esc([p.employee,...(Array.isArray(p.team)?p.team.map(x=>x.name):[])].filter(Boolean).join(', '))}</td><td>${esc(p.qty)} ${esc(p.unit)}</td><td>${esc(p.lot||'—')}</td><td><span class="status">${p.status==='completed'?'FINALIZADA':'EN PROCESO'}</span></td><td>${p.status==='completed'?`<button class="btn" data-action="label" data-id="${p.id}">Etiqueta</button>`:`<button class="btn primary" data-action="finish-existing" data-id="${p.id}">✓ Finalizar</button>`} <button class="btn" data-action="edit-production" data-id="${p.id}">Editar</button> <button class="btn danger" data-action="delete-production" data-id="${p.id}">Eliminar</button></td></tr>`).join('')||`<tr><td colspan="10" class="empty">No hay producciones.</td></tr>`}</tbody></table></div></div>`;
}
function fridgeSummary(){const out={};for(const m of (state.refrigerationMoves||[])){const k=String(m.productId||m.product||'').toLowerCase();if(!out[k])out[k]={product:m.product,unit:m.unit||'u',qty:0,in:0,out:0,moves:0,firstDate:m.date,lastDate:m.date,avgDaily:0};const x=out[k],q=Math.max(0,Number(m.qty||0));if(m.type==='SALIDA'){x.qty-=q;x.out+=q}else{x.qty+=q;x.in+=q}x.moves++;if(String(m.date)<String(x.firstDate))x.firstDate=m.date;if(String(m.date)>String(x.lastDate))x.lastDate=m.date}Object.values(out).forEach(x=>{const days=Math.max(1,(Date.now()-new Date(x.firstDate||Date.now()).getTime())/86400000);x.avgDaily=x.out/days;x.qty=Math.max(0,x.qty)});return out}
function fridgeMoveModal(){const names=[...(state.preps||[]),...(state.recipes||[]),...(master.preps||[]),...(master.recipes||[])].filter((r,i,a)=>a.findIndex(x=>String(x.id)===String(r.id))===i);modal(`<h3>Movimiento de nevera</h3><div class="formgrid"><div class="field full"><label>Producto / pre-elaborado</label><input id="fmProduct" list="fridgeProducts"><datalist id="fridgeProducts">${names.map(x=>`<option value="${esc(x.name)}">`).join('')}</datalist></div><div class="field"><label>Movimiento</label><select id="fmType"><option value="ENTRADA">Entró</option><option value="SALIDA">Salió</option></select></div><div class="field"><label>Cantidad</label><input id="fmQty" type="number" step="0.01" min="0.001"></div><div class="field"><label>Unidad / envase</label><input id="fmUnit" value="L"></div><div class="field"><label>Responsable</label><input id="fmResp" value="${esc(currentUser().name||'')}" ></div><div class="field"><label>Fecha / hora</label><input id="fmDate" type="datetime-local" value="${new Date().toISOString().slice(0,16)}"></div><div class="field full"><label>Notas</label><textarea id="fmNotes" rows="2" placeholder="Ej.: container 1 L, cambio de envase, traslado, devolución..."></textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-fridge-move">Guardar movimiento</button></div>`)}
function saveFridgeMove(){const product=document.getElementById('fmProduct').value.trim(),type=document.getElementById('fmType').value,qty=Number(document.getElementById('fmQty').value||0),unit=document.getElementById('fmUnit').value.trim()||'u';if(!product||qty<=0)return toast('Completa producto y cantidad');const all=[...(state.preps||[]),...(state.recipes||[]),...(master.preps||[]),...(master.recipes||[])],r=all.find(x=>String(x.name).trim().toLowerCase()===product.toLowerCase()),date=document.getElementById('fmDate').value?new Date(document.getElementById('fmDate').value).toISOString():now();const current=fridgeSummary()[String(r?.id||product).toLowerCase()];if(type==='SALIDA'&&(!current||Number(current.qty)<qty))return toast(`No hay suficiente existencia en nevera. Disponible: ${fmtNum(current?.qty||0)} ${unit}`);state.refrigerationMoves.push({id:'FRG-'+Date.now(),date,type,product,productId:r?.id||'',qty,unit,responsible:document.getElementById('fmResp').value.trim(),notes:document.getElementById('fmNotes').value.trim(),createdAt:now()});save();close();render();toast(type==='SALIDA'?'Salida de nevera registrada':'Entrada a nevera registrada')}
function fridgeReport(){const moves=state.refrigerationMoves||[],by={};moves.forEach(m=>{const k=String(m.productId||m.product).toLowerCase();if(!by[k])by[k]={key:k,product:m.product,productId:m.productId||'',unit:m.unit||'u',entries:0,exits:0,current:0};const q=Number(m.qty||0);if(m.type==='SALIDA'){by[k].exits+=q;by[k].current-=q}else{by[k].entries+=q;by[k].current+=q}});const rows=Object.values(by).map(x=>{const pm=moves.filter(m=>String(m.productId||m.product).toLowerCase()===String(x.productId||x.product).toLowerCase());const days=Math.max(1,(new Date(Math.max(...pm.map(m=>new Date(m.date).getTime()))) - new Date(Math.min(...pm.map(m=>new Date(m.date).getTime()))))/86400000+1);return {...x,current:Math.max(0,x.current),avgDaily:x.exits/days}});modal(`<h3>Reporte de flujo de nevera</h3><p class="muted">Métricas basadas exclusivamente en movimientos registrados.</p><div class="tablewrap"><table><thead><tr><th>Producto</th><th>Entradas</th><th>Salidas</th><th>Existencia</th><th>Promedio salida/día</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.product)}</td><td>${fmtNum(x.entries)} ${esc(x.unit)}</td><td>${fmtNum(x.exits)} ${esc(x.unit)}</td><td><b>${fmtNum(x.current)} ${esc(x.unit)}</b></td><td>${fmtNum(x.avgDaily,2)} ${esc(x.unit)}</td></tr>`).join('')||'<tr><td colspan="5">Sin datos.</td></tr>'}</tbody></table></div><div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)}
function fridgePlanning(){
 const moves=state.refrigerationMoves||[], nowMs=Date.now();
 const periods=[7,30,90];
 const calc=(days)=>{const from=nowMs-days*86400000;const by={};moves.filter(m=>new Date(m.date).getTime()>=from).forEach(m=>{const k=String(m.productId||m.product||'').toLowerCase();if(!by[k])by[k]={product:m.product,productId:m.productId||'',unit:m.unit||'u',entries:0,exits:0};const q=Math.max(0,Number(m.qty||0));if(m.type==='SALIDA')by[k].exits+=q;else by[k].entries+=q});return Object.values(by).map(x=>{const avg=x.exits/days;const current=(fridgeSummary()[String(x.productId||x.product).toLowerCase()]?.qty||0);return {...x,current,avgDaily:avg,daysCoverage:avg>0?current/avg:null,recommended:x.entries===0&&avg>0?avg*days:Math.max(0,avg)}}).sort((a,b)=>b.avgDaily-a.avgDaily)};
 const sets=periods.map(d=>({days:d,rows:calc(d)}));
 const body=sets.map(({days,rows})=>`<div style="margin-top:14px"><h4>Últimos ${days} días</h4><div class="tablewrap"><table><thead><tr><th>Producto</th><th>Entradas</th><th>Salidas</th><th>Existencia</th><th>Promedio/día</th><th>Cobertura</th><th>Referencia de producción</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.product)}</b></td><td>${fmtNum(x.entries)} ${esc(x.unit)}</td><td>${fmtNum(x.exits)} ${esc(x.unit)}</td><td>${fmtNum(x.current,2)} ${esc(x.unit)}</td><td>${fmtNum(x.avgDaily,2)} ${esc(x.unit)}/día</td><td>${x.daysCoverage===null?'—':fmtNum(x.daysCoverage,1)+' días'}</td><td>${fmtNum(x.recommended,2)} ${esc(x.unit)}<small class="muted"> referencia analítica; no crea producción automática</small></td></tr>`).join('')||'<tr><td colspan=7 class=empty>Sin movimientos en este período.</td></tr>'}</tbody></table></div></div>`).join('');
 modal(`<h3>Planeación de producción por flujo de nevera</h3><p class="muted">Usa únicamente salidas registradas. Sirve para decidir frecuencia y tamaño de lote; no modifica Food Cost ni crea órdenes automáticamente.</p>${body}<div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`);
}
function exportFridge(){const rows=(state.refrigerationMoves||[]).map(x=>({...x}));exportRows(rows,'LRX_Nevera_Flujo');exportExcel(rows,'LRX_Nevera_Flujo')}
