function readSaleItems(){return [...document.querySelectorAll('#saleItems .sale-item-row')].map(row=>({product:row.querySelector('.sale-item-product')?.value.trim(),qty:Number(row.querySelector('.sale-item-qty')?.value||0),price:Number(row.querySelector('.sale-item-price')?.value||0)})).filter(x=>x.product&&x.qty>0&&x.price>=0)}
function previewSale(){const box=document.getElementById('salePreview');if(!box)return;const items=readSaleItems(),d=Number(document.getElementById('saleDiscount')?.value||0),c=Number(document.getElementById('saleCommission')?.value||0),card=Number(document.getElementById('saleCard')?.value||0);let gross=0,cost=0;for(const x of items){const r=allRecipes().find(y=>String(y.name||'').trim().toLowerCase()===x.product.toLowerCase());gross+=x.price*x.qty;cost+=r?recipeCostDetail(r).cost/Math.max(1,Number(r.yieldQty||1))*x.qty:0}const disc=gross*d/100,net=gross-disc-(gross-disc)*c/100-card;box.innerHTML=`${items.length} artículo(s) · Bruto <b>${money(gross)}</b> · Descuento <b>${money(disc)}</b> · Neto <b>${money(net)}</b> · Costo <b>${money(cost)}</b> · Utilidad <b>${money(net-cost)}</b>`}
