function saveDiet(id=''){
 const name=document.getElementById('diProduct').value.trim(),person=document.getElementById('diPerson').value.trim(),qty=Number(document.getElementById('diQty').value||0);if(!name||!person||qty<=0)return toast('Completa persona, producto y cantidad');
 const allP=[...(master.products||[]),...(state.products||[])],rec=allRecipes().find(x=>String(x.name).toLowerCase()===name.toLowerCase());let unitCost=0,sourceId='';
 if(rec){const d=recipeCostDetail(rec),y=Number(rec.yieldQty||1);unitCost=y?d.cost/y:d.cost;sourceId=rec.id}else{const p=allP.find(x=>String(x.name).toLowerCase()===name.toLowerCase());if(!p)return toast('Producto/receta no encontrado en el maestro');unitCost=Number(p.usableCost??p.cost??p.finalCost??0);sourceId=p.id}
 const total=unitCost*qty,lost=Number(document.getElementById('diLost').value||0),date=document.getElementById('diDate').value?new Date(document.getElementById('diDate').value).toISOString():now();
 const obj={id:id||'DIET-'+Date.now(),date,person,product:name,productId:sourceId,qty,unit:document.getElementById('diUnit').value.trim()||'u',cost:total,unitCost,lostSales:lost,authorizedBy:document.getElementById('diAuth').value.trim(),type:document.getElementById('diType').value,notes:document.getElementById('diNote').value.trim(),createdAt:id?((state.employeeConsumptions||[]).find(x=>x.id===id)?.createdAt||now()):now(),updatedAt:now()};
 const old=id?(state.employeeConsumptions||[]).find(x=>String(x.id)===String(id)):null;
 const reverseDiet=(r)=>{for(const m of (state.movements||[]).filter(x=>String(x.ref)===String(r?.id)&&x.type==='CONSUMO INTERNO')){const inv=(state.inventory||[]).find(i=>(m.productId&&String(i.productId||i.id)===String(m.productId))||String(i.product||'').toLowerCase()===String(m.product||'').toLowerCase());if(inv)inv.qty=Number(inv.qty||0)-Number(m.qty||0)}state.movements=(state.movements||[]).filter(x=>!(String(x.ref)===String(r?.id)&&x.type==='CONSUMO INTERNO'))};
 if(old)reverseDiet(old);
 const moves=state.movements||[];
 const deduct=(productName,productId,amount,unit)=>{const inv=(state.inventory||[]).find(x=>(productId&&String(x.productId||x.id)===String(productId))||String(x.product||'').trim().toLowerCase()===String(productName||'').trim().toLowerCase());if(!inv||Number(inv.qty||0)<amount)return false;inv.qty=Number(inv.qty||0)-amount;inv.updatedAt=now();moves.push({id:'MOV-DIET-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:obj.date,type:'CONSUMO INTERNO',product:inv.product,productId:inv.productId||inv.id,qty:-amount,unit:unit||inv.unit||'',ref:obj.id,reason:'Dieta / consumo interno',createdAt:now()});return true};
 let failed=false;
 if(rec){const y=Math.max(1,Number(rec.yieldQty||1));for(const it of (rec.items||[])){const q=Number(it.qty||0)/y*qty;if(q>0&&!deduct(it.product||it.ingredient||it.name,it.productId||it.ingredientId,q,it.unit||'u'))failed=true}}
 else if(!deduct(name,sourceId,qty,obj.unit))failed=true;
 if(failed){reverseDiet(obj);return toast('No hay existencia suficiente o falta vínculo de inventario')}
 state.movements=moves;const arr=state.employeeConsumptions||[],ix=arr.findIndex(x=>String(x.id)===String(obj.id));if(ix>=0)arr[ix]=obj;else arr.push(obj);state.employeeConsumptions=arr;
 state.dreRecords=state.dreRecords||[];state.dreRecords=state.dreRecords.filter(x=>x.sourceId!==obj.id);state.dreRecords.push({id:'DRE-DIET-'+obj.id,date:obj.date,type:'expense',category:'Consumos internos',description:`${obj.type}: ${obj.person} — ${obj.product}`,amount:obj.cost,source:'DIETA',sourceId:obj.id,createdAt:now()});save();close();render();toast(id?'Consumo actualizado':'Consumo registrado');
}
